      "content": "{\n  \"name\": \"@alexpeng/dsh-custom-plugin\",\n  \"description\": \"Custom convenience suite for the dsh web GUI: appearance, folders, prompts, session export/search, Mermaid, quote reply, usage analytics, local budget, key-free backups, and a Ctrl/Cmd+K command palette; dual-face plugin mounted without dsh source changes.\",\n  \"version\": \"0.9.1\",\n  \"type\": \"module\",\n  \"icon\": \"./icon.svg\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-chat\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\"\n      ]\n    }\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AlexPeng07/dsh-custom-plugin.git\"\n  },\n  \"author\": \"AlexPeng <alexpeng07@outlook.com>\",\n  \"bugs\": \"https://github.com/AlexPeng07/dsh-custom-plugin/issues\",\n  \"homepage\": \"https://github.com/AlexPeng07/dsh-custom-plugin#readme\",\n  \"engines\": {\n    \"node\": \">=22\",\n    \"dsh\": \">=0.1.7-rc.2\"\n  },\n  \"packageManager\": \"pnpm@11.28.5\",\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.build.json && tsdown\",\n    \"bundle\": \"tsdown\",\n    \"watch\": \"tsdown --watch\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\",\n    \"check:readme\": \"node scripts/check-readme-i18n.mjs\",\n    \"smoke\": \"node scripts/smoke.mjs\",\n    \"canary\": \"node scripts/compat-canary.mjs\",\n    \"prepare\": \"npm run build\",\n    \"prepublishOnly\": \"tsc --noEmit && vitest run\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4\",\n    \"@deepseek-ai/dsh-tools\": \">=0.1.7-rc.2\"\n  },\n  \"dependencies\": {\n    \"mermaid\": \"^11.6.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-session-query\": \"0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.3\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"^18.3.5\",\n    \"puppeteer-core\": \"^25.8.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"semver\": \"^7.8.5\",\n    \"tsdown\": \"0.22.2\",\n    \"typescript\": \"~5.7.2\",\n    \"vitest\": \"^3.0.0\"\n  },\n  \"files\": [\n    \"lib\",\n    \"locale/*.json\",\n    \"icon.svg\",\n    \"cordis.patch.yml\",\n    \"CHANGELOG.md\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"README.i18n.yaml\"\n  ],\n  \"license\": \"Apache-2.0\"\n}\n"
