      "path": "src/index.ts",
      "content": "/**\n * Host loader entry for dsh-custom-plugin.\n *\n * The Host owns the state document, the daily token-usage ledger (folded\n * from `session/event`), the `/api/custom-plugin` routes (state, timeline,\n * export, backup, search, balance, usage scan, Mermaid fetch, diagnostics), and the\n * `custom_plugin_status` agent tool. The browser is a same-origin view over\n * those routes; this half has no UI of its own.\n * @module @alexpeng/dsh-custom-plugin\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Session, SessionEvent } from '@deepseek-ai/dsh-session'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { join } from 'node:path'\nimport { dshHome } from './dsh-home.ts'\nimport { mountOnce } from './mount-once.ts'\nimport { defaultState, loadStateFile, saveStateFile, STATE_FILE } from './state.ts'\nimport { CustomPluginHost } from './host-service.ts'\nimport { makeCustomPluginRoutes } from './routes.ts'\nimport { dayKey } from './usage.ts'\n\nexport const inject = ['webServer', 'tools', 'sessionQuery']\n\nexport const apply = mountOnce('@alexpeng/dsh-custom-plugin', applyImpl)\n\nfunction applyImpl(ctx: Context): void {\n  const state = defaultState()\n  // Keep diagnostics truthful even before the asynchronous load resolves.\n  // `dshHome()` is a directory; the state path is its sibling file.\n  let statePath = join(dshHome(), STATE_FILE)\n  let stateLoaded = false\n  // Flipped only when the state file could be neither read nor quarantined\n  // aside: every save path funnels through `saveNow`/`saveSoon`, so gating\n  // here keeps the host from persisting never-loaded defaults over a\n  // document that may still be intact on disk.\n  let stateWritable = true\n  const sessionModels = new Map<string, string | null>()\n  const pendingUsage: Array<{ sessionId: string; usage: NonNullable<Extract<SessionEvent, { type: 'assistant/message' }>['data']['usage']>; time: number; model: string | null }> = []\n\n  const diagReports: string[] = []\n  const reportDiag = (message: string): void => {\n    diagReports.push(String(message ?? '').slice(0, 400))\n    if (diagReports.length > 20) diagReports.splice(0, diagReports.length - 20)\n  }\n\n  const saveSoon = (() => {\n    let timer: ReturnType<typeof setTimeout> | undefined\n    return (): void => {\n      if (!stateWritable) return\n      if (timer !== undefined) clearTimeout(timer)\n      timer = setTimeout(() => {\n        timer = undefined\n        void host.persistWhenIdle().catch((error) => {\n          reportDiag(`state save failed: ${String((error as Error)?.message ?? error)}`)\n        })\n      }, 500)\n    }\n  })()\n\n  const host = new CustomPluginHost({\n    sessionQuery: ctx.sessionQuery,\n    state,\n    statePath: () => statePath,\n    saveNow: () => (stateWritable ? saveStateFile(state) : Promise.resolve()),\n    reportDiag,\n    diagReports,\n    attachments: ctx.get('attachments'),\n  })\n\n  const stateReady = loadStateFile(state).then(async (path) => {\n    statePath = path\n    if (await host.migrateLegacyApiKey()) reportDiag('legacy API key migrated to system credentials')\n    stateLoaded = true\n    for (const item of pendingUsage.splice(0)) host.foldUsage(item.sessionId, item.usage, item.time, item.model ?? undefined)\n    try {\n      await saveStateFile(state)\n    } catch (error) {\n      // The load itself succeeded; a failed normalization save (full disk,\n      // read-only home) must not flip the host read-only — later saves retry.\n      reportDiag(`state save failed: ${String((error as Error)?.message ?? error)}`)\n    }\n  }).catch((error) => {\n    // The document could be neither read nor preserved aside. Keep the host\n    // usable but read-only: events still fold in memory, while saves are\n    // suppressed — persisting the never-loaded defaults would destroy the\n    // very file the plugin could not read.\n    reportDiag(`state file unreadable, running read-only: ${String((error as Error)?.message ?? error)}`)\n    stateWritable = false\n    stateLoaded = true\n    for (const item of pendingUsage.splice(0)) host.foldUsage(item.sessionId, item.usage, item.time, item.model ?? undefined)\n  })\n\n  // Daily token usage: fold request/context (model) + assistant/message (usage).\n  ctx.on('session/event', (session: Session, event: SessionEvent) => {\n    try {\n      if (event === undefined || event === null) return\n      const sessionId = String(session.id)\n      if (event.type === 'request/context') {\n        const model = event.data.model ?? null\n        sessionModels.set(sessionId, model)\n        host.rememberModel(sessionId, model)\n      } else if (event.type === 'assistant/message' && event.data.usage !== undefined) {\n        if (!stateLoaded) pendingUsage.push({ sessionId, usage: event.data.usage, time: event.time, model: sessionModels.get(sessionId) ?? null })\n        else {\n          host.foldUsage(sessionId, event.data.usage, event.time)\n          saveSoon()\n        }\n      }\n    } catch (error) {\n      reportDiag(`usage fold failed: ${String((error as Error)?.message ?? error)}`)\n    }\n  })\n  ctx.on('session/disposed', (session: Session) => {\n    const sessionId = String(session.id)\n    sessionModels.delete(sessionId)\n    host.forgetSession(sessionId)\n  })\n\n  // Routes: state document, timeline, export, backup, search, balance, usage scan, Mermaid.\n  const routeDisposers: Array<() => void> = []\n  for (const route of makeCustomPluginRoutes(host, stateReady)) {\n    routeDisposers.push(ctx.webServer.register(route))\n  }\n\n  // Preheat the Mermaid engine (local dependency first, CDN fallback) so the\n  // first diagram render in the browser does not pay the load latency.\n  void host.mermaidFetch().then((result) => {\n    reportDiag(result.ok ? `mermaid engine ready (${result.bytes} bytes, ${host.mermaidLoadedSource()})` : `mermaid engine failed: ${result.error}`)\n  }).catch((error) => {\n    reportDiag(`mermaid preheat failed: ${String((error as Error)?.message ?? error)}`)\n  })\n\n  // The status tool: appearance config, today's usage, balance, timeline sample.\n  const disposeTool = ctx.tools.register(defineTool({\n    name: 'custom_plugin_status',\n    description: '查看 Custom 便利套件（dsh-custom-plugin）运行状态：外观配置、今日 token 用量（按模型）、DeepSeek 余额（如已配置 API Key）、当前会话时间线样本、Mermaid 引擎加载情况、客户端注入诊断。',\n    parameters: {},\n    output: {\n      schema: { type: 'object', additionalProperties: true },\n      render: (_args, value) => {\n        const v = (value ?? {}) as Record<string, unknown>\n        const lines: string[] = []\n        lines.push(`Custom 便利套件状态 (今日 ${String(v.today ?? '?')})`)\n        lines.push(`外观配置: ${JSON.stringify(v.cfg ?? {})}`)\n        lines.push(`今日用量: ${JSON.stringify(v.usageToday ?? {})}`)\n        if (v.balance !== undefined && v.balance !== null) {\n          const balance = v.balance as { currency?: string; total?: string }\n          lines.push(`余额: ${String(balance.currency ?? '')} ${String(balance.total ?? '')}`)\n        }\n        if (typeof v.balanceError === 'string' && v.balanceError !== '') lines.push(`余额错误: ${v.balanceError}`)\n        if (Array.isArray(v.timelineSample)) lines.push(`时间线样本: ${JSON.stringify(v.timelineSample)}`)\n        lines.push(`Mermaid 引擎: ${String(v.mermaidBytes ?? 0)} bytes; 状态文件: ${String(v.statePath ?? '')}`)\n        if (Array.isArray(v.diagReports) && v.diagReports.length > 0) lines.push(`客户端诊断: ${v.diagReports.join(' | ')}`)\n        return [{ type: 'text', text: lines.join('\\n') }]\n      },\n    },\n    // eslint-disable-next-line @typescript-eslint/no-explicit-any\n    async execute(): Promise<Record<string, any>> {\n      await stateReady\n      const out: Record<string, unknown> = {\n        today: dayKey(),\n        cfg: state.cfg,\n        usageToday: state.usage[dayKey()] ?? {},\n        mermaidBytes: host.mermaidBytes(),\n        statePath,\n        apiKeyConfigured: await host.hasApiKey(),\n        diagReports: [...diagReports],\n      }\n      const agents = ctx.get('agents') as { currentInitiator?(): { id: unknown } } | undefined\n      const agent = agents !== undefined && typeof agents.currentInitiator === 'function' ? agents.currentInitiator() : null\n      const sessionId = agent !== null && agent !== undefined ? String(agent.id) : null\n      if (sessionId !== null) {\n        const timeline = await host.timelineGet(sessionId)\n        out.timelineSample = timeline.ok\n          ? (timeline.items ?? []).slice(0, 2).map((item) => ({ seq: item.seq, time: item.time, text: item.text.slice(0, 120) }))\n          : timeline.error\n      }\n      const balance = await host.balanceGet()\n      out.balance = balance.ok ? balance.balance : null\n      out.balanceError = balance.ok ? null : balance.error\n      return out\n    },\n  }))\n\n  ctx.effect(() => {\n    const dispose = routeDisposers.splice(0)\n    return () => { for (const item of dispose) item() }\n  }, 'custom-plugin: host routes')\n\n  ctx.effect(() => () => { disposeTool() }, 'custom-plugin: status tool')\n}\n"
    },
    {
      "path": "src/routes.ts",
      "content": "/**\n * HTTP routes for dsh-custom-plugin.\n *\n * Every route sits behind the loopback trust fence (shared `loopback.ts`,\n * semantics aligned with the platform's own request fence); the browser talks\n * to these handlers with plain fetch. The mermaid engine script is served at\n * its own non-API path because the browser loads it as a `<script src>`.\n * @module @alexpeng/dsh-custom-plugin/routes\n */\n\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { WebRoute } from '@deepseek-ai/dsh-host-webserver'\nimport type { CustomPluginHost } from './host-service.ts'\nimport { isLoopbackRequest } from './loopback.ts'\nimport { CUSTOM_PLUGIN_API_PREFIX, MERMAID_SCRIPT_PATH } from './protocol.ts'\nimport { BACKUP_BODY_LIMIT } from './backup.ts'\n\nexport const STATE_BODY_LIMIT = 1024 * 1024\nconst TIMELINE_LIMIT = 64 * 1024\n// The request envelope contains JSON keys around the document. Keep a small\n// reserve so a document at the documented 5 MiB limit is not rejected solely\n// because of that envelope; the document itself is checked below as well.\nconst BACKUP_REQUEST_LIMIT = BACKUP_BODY_LIMIT + 64 * 1024\n\nfunction json(res: ServerResponse, status: number, body: unknown): void {\n  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n  res.end(JSON.stringify(body))\n}\n\n/**\n * The request fence. Trust is decided by `isLoopbackRequest` alone: a loopback\n * socket with a loopback Host, a non-`cross-site` fetch marker, and an Origin\n * that is absent or matches the Host authority. Absent markers are *accepted*\n * — that is the exact header shape dsh Desktop's shell produces when it\n * forwards renderer requests to its own Host (it deletes `host`, `origin`,\n * `sec-fetch-site` and `cookie` first), and the same shape the platform fence\n * treats as trusted. A foreign origin, a cross-site marker, or a non-loopback\n * peer is rejected.\n */\nfunction guard(req: IncomingMessage, res: ServerResponse): boolean {\n  if (isLoopbackRequest(req)) return true\n  json(res, 403, { ok: false, error: 'forbidden' })\n  return false\n}\n\nasync function readBody(req: IncomingMessage, limit: number): Promise<unknown> {\n  const chunks: Buffer[] = []\n  let size = 0\n  for await (const chunk of req) {\n    const buffer = chunk as Buffer\n    size += buffer.length\n    if (size > limit) throw new Error('body-too-large')\n    chunks.push(buffer)\n  }\n  if (chunks.length === 0) return {}\n  return JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown\n}\n\nfunction isMethod(req: IncomingMessage, method: string, res: ServerResponse): boolean {\n  if (req.method === method) return true\n  json(res, 405, { ok: false, error: 'method-not-allowed' })\n  return false\n}\n\n/** Build the plugin's route set. */\nexport function makeCustomPluginRoutes(host: CustomPluginHost, ready: Promise<void> = Promise.resolve()): WebRoute[] {\n  const stateRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/state`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      await ready\n      if (req.method === 'GET') {\n        json(res, 200, { ok: true, data: await host.stateView() })\n        return\n      }\n      if (req.method !== 'POST') {\n        json(res, 405, { ok: false, error: 'method-not-allowed' })\n        return\n      }\n      try {\n        const rawBody = await readBody(req, STATE_BODY_LIMIT)\n        if (rawBody === null || typeof rawBody !== 'object' || Array.isArray(rawBody)) {\n          json(res, 400, { ok: false, error: '状态请求结构无效' })\n          return\n        }\n        const body = rawBody as Record<string, unknown>\n        await host.applyEdit({\n          cfg: body.cfg as never,\n          folders: Array.isArray(body.folders) ? (body.folders as never) : undefined,\n          prompts: Array.isArray(body.prompts) ? (body.prompts as never) : undefined,\n          stars: body.stars as never,\n          apiKey: typeof body.apiKey === 'string' ? body.apiKey : undefined,\n        })\n        await host.persistWhenIdle()\n        json(res, 200, { ok: true, ...(await host.credentialStatus()) })\n      } catch (error) {\n        const message = error instanceof Error ? error.message : String(error)\n        json(res, message === 'body-too-large' ? 413 : 400, { ok: false, error: message })\n      }\n    },\n  }\n\n  const timelineRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/timeline`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      if (!isMethod(req, 'GET', res)) return\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const sessionId = url.searchParams.get('sessionId') ?? ''\n      if (sessionId === '') {\n        json(res, 400, { ok: false, error: 'no sessionId' })\n        return\n      }\n      const result = await host.timelineGet(sessionId)\n      json(res, result.ok ? 200 : 500, result)\n    },\n  }\n\n  const backupRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/backup`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      await ready\n      if (req.method === 'GET') {\n        json(res, 200, { ok: true, data: host.backupExport() })\n        return\n      }\n      if (!isMethod(req, 'POST', res)) return\n      try {\n        const rawBody = await readBody(req, BACKUP_REQUEST_LIMIT)\n        if (rawBody === null || typeof rawBody !== 'object' || Array.isArray(rawBody)) {\n          json(res, 400, { ok: false, error: '备份请求结构无效' })\n          return\n        }\n        const body = rawBody as Record<string, unknown>\n        if (body.mode !== 'merge' && body.mode !== 'replace') {\n          json(res, 400, { ok: false, error: '导入模式无效' })\n          return\n        }\n        if (!Object.prototype.hasOwnProperty.call(body, 'document')) {\n          json(res, 400, { ok: false, error: '备份文档缺失' })\n          return\n        }\n        if (body.dryRun !== undefined && typeof body.dryRun !== 'boolean') {\n          json(res, 400, { ok: false, error: 'dryRun 字段无效' })\n          return\n        }\n        const encodedDocument = JSON.stringify(body.document)\n        if (encodedDocument === undefined) {\n          json(res, 400, { ok: false, error: '备份文档无效' })\n          return\n        }\n        if (Buffer.byteLength(encodedDocument, 'utf8') > BACKUP_BODY_LIMIT) {\n          json(res, 413, { ok: false, error: '备份文档不能超过 5 MB' })\n          return\n        }\n        const result = await host.backupImport(body.document, body.mode, body.dryRun === true)\n        json(res, result.ok ? 200 : 400, result)\n      } catch (error) {\n        const message = error instanceof Error ? error.message : String(error)\n        json(res, message === 'body-too-large' ? 413 : 400, { ok: false, error: message })\n      }\n    },\n  }\n\n  const searchRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/search`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      if (!isMethod(req, 'POST', res)) return\n      try {\n        const body = (await readBody(req, TIMELINE_LIMIT)) as { sessionId?: string; query?: string; kinds?: unknown }\n        if (typeof body.sessionId !== 'string' || body.sessionId === '' || typeof body.query !== 'string' || body.query.trim() === '') {\n          json(res, 400, { ok: false, error: '会话或搜索词为空' })\n          return\n        }\n        const allowed = new Set(['user', 'assistant', 'tool'])\n        if (body.kinds !== undefined && !Array.isArray(body.kinds)) {\n          json(res, 400, { ok: false, error: '角色筛选无效' })\n          return\n        }\n        if (Array.isArray(body.kinds) && body.kinds.some((kind) => typeof kind !== 'string' || !allowed.has(kind))) {\n          json(res, 400, { ok: false, error: '角色筛选无效' })\n          return\n        }\n        const kinds = Array.isArray(body.kinds) ? body.kinds as Array<'user' | 'assistant' | 'tool'> : []\n        const result = await host.conversationSearch(body.sessionId, body.query.trim(), kinds)\n        json(res, result.ok ? 200 : 500, result)\n      } catch (error) {\n        const message = error instanceof Error ? error.message : String(error)\n        json(res, message === 'body-too-large' ? 413 : 400, { ok: false, error: message })\n      }\n    },\n  }\n\n  const exportRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/export`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      if (!isMethod(req, 'POST', res)) return\n      try {\n        const body = (await readBody(req, TIMELINE_LIMIT)) as { sessionId?: string; format?: string }\n        if (typeof body.sessionId !== 'string' || body.sessionId === '') {\n          json(res, 400, { ok: false, error: 'no sessionId' })\n          return\n        }\n        const result = await host.exportRun(body.sessionId, body.format ?? 'json')\n        json(res, result.ok ? 200 : 500, result)\n      } catch (error) {\n        const message = error instanceof Error ? error.message : String(error)\n        json(res, message === 'body-too-large' ? 413 : 400, { ok: false, error: message })\n      }\n    },\n  }\n\n  const balanceRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/balance`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      await ready\n      if (!isMethod(req, 'GET', res)) return\n      try {\n        const result = await host.balanceGet()\n        // 200 either way: the { ok, error } envelope carries the failure detail\n        // (e.g. \"key not configured\") the panel renders.\n        json(res, 200, result)\n      } catch (error) {\n        json(res, 500, { ok: false, keyConfigured: false, error: String((error as Error)?.message ?? error) })\n      }\n    },\n  }\n\n  const usageScanRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/usage-scan`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      await ready\n      if (!isMethod(req, 'POST', res)) return\n      try {\n        const result = await host.usageScan()\n        json(res, result.ok ? 200 : 500, result)\n      } catch (error) {\n        json(res, 500, { ok: false, error: String((error as Error)?.message ?? error) })\n      }\n    },\n  }\n\n  const mermaidFetchRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/mermaid`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      if (!isMethod(req, 'POST', res)) return\n      try {\n        const result = await host.mermaidFetch()\n        json(res, result.ok ? 200 : 502, result)\n      } catch (error) {\n        json(res, 502, { ok: false, error: String((error as Error)?.message ?? error) })\n      }\n    },\n  }\n\n  const mermaidScriptRoute: WebRoute = {\n    kind: 'exact',\n    path: MERMAID_SCRIPT_PATH,\n    handler: (req, res): void => {\n      // Same fence as the API routes: a same-origin or unmarked loopback load\n      // passes (web pages send sec-fetch-site: same-origin; dsh Desktop's\n      // shell forwards the load without markers), a cross-site page does not.\n      if (!guard(req, res)) return\n      const script = host.mermaidScript()\n      if (script === '') {\n        res.statusCode = 503\n        res.end('mermaid bundle not ready')\n        return\n      }\n      const etag = `\"${host.mermaidEtag()}\"`\n      res.setHeader('ETag', etag)\n      res.setHeader('Cache-Control', 'no-cache')\n      const ifNoneMatch = req.headers['if-none-match']\n      if (typeof ifNoneMatch === 'string' && ifNoneMatch.split(',').some((value) => value.trim() === etag)) {\n        // Reloads revalidate instead of re-transferring the 3.5 MB engine;\n        // the hash changes only when the engine content does.\n        res.statusCode = 304\n        res.end()\n        return\n      }\n      res.statusCode = 200\n      res.setHeader('Content-Type', 'text/javascript; charset=utf-8')\n      res.setHeader('Content-Length', String(Buffer.byteLength(script, 'utf8')))\n      res.end(script)\n    },\n  }\n\n  const diagRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/diag`,\n    handler: async (req, res): Promise<void> => {\n      if (!guard(req, res)) return\n      if (!isMethod(req, 'POST', res)) return\n      try {\n        const body = (await readBody(req, 4 * 1024)) as { msg?: string }\n        if (typeof body.msg === 'string') host.pushDiag(body.msg)\n      } catch {\n        // diagnostics are best-effort\n      }\n      json(res, 200, { ok: true })\n    },\n  }\n\n  const debugRoute: WebRoute = {\n    kind: 'exact',\n    path: `${CUSTOM_PLUGIN_API_PREFIX}/debug`,\n    handler: (req, res): void => {\n      if (!guard(req, res)) return\n      if (!isMethod(req, 'GET', res)) return\n      void ready.then(() => host.debugInfo()).then((info) => { json(res, 200, { ok: true, ...info }) }).catch(() => { json(res, 200, { ok: false, error: '调试信息不可用' }) })\n    },\n  }\n\n  return [stateRoute, timelineRoute, backupRoute, searchRoute, exportRoute, balanceRoute, usageScanRoute, mermaidFetchRoute, mermaidScriptRoute, diagRoute, debugRoute]\n}\n"
    },
    {
      "path": "src/loopback.ts",
      "content": "/**\n * Loopback trust fence for the host routes: socket address, Host header, and\n * browser same-origin markers.\n *\n * Semantics: RFC 5735 IPv4 127/8, ::1, IPv4-mapped ::ffff:127/8, localhost\n * hostnames. The request-level fence mirrors the platform's own API fence: a\n * loopback peer naming a loopback Host is trusted unless a marker says\n * otherwise — `sec-fetch-site: cross-site` rejects, and a present Origin must\n * match the Host authority. Absent markers are trusted: that is the header\n * shape dsh Desktop's shell produces when it forwards renderer requests to\n * its Host (it deletes `origin`, `sec-fetch-site` and `cookie` first), and\n * the shape the platform fence accepts for the same reason.\n * @module @alexpeng/dsh-custom-plugin/loopback\n */\n\nimport type { IncomingMessage } from 'node:http'\n\n/** IPv4 127/8 predicate (four decimal octets, first == 127). */\nexport function isIPv4Loopback(v4: string): boolean {\n  const parts = v4.split('.')\n  return parts.length === 4\n    && parts[0] === '127'\n    && parts.every(part => /^\\d{1,3}$/.test(part) && Number(part) <= 255)\n}\n\n/** Whether a socket remote address names the loopback range (127/8, ::1, IPv4-mapped). */\nexport function isLoopbackAddress(address: string | undefined): boolean {\n  if (address === undefined) return false\n  const normalized = address.toLowerCase()\n  if (normalized === '::1') return true\n  if (normalized.startsWith('::ffff:')) return isIPv4Loopback(normalized.slice('::ffff:'.length))\n  return isIPv4Loopback(normalized)\n}\n\n/** Whether a normalized URL hostname names the loopback authority (localhost, [::1], 127/8). */\nexport function isLoopbackHostname(hostname: string): boolean {\n  if (hostname === 'localhost' || hostname === '[::1]') return true\n  return isIPv4Loopback(hostname)\n}\n\n/**\n * Request-level trust fence, mirroring the platform fence's semantics: a\n * loopback socket address AND a loopback Host header, non-`cross-site` fetch\n * marker, and an Origin that is absent (trusted — the dsh Desktop forward\n * shape) or matches the Host authority. The socket address is authoritative;\n * X-Forwarded-For is never trusted.\n */\nexport function isLoopbackRequest(request: IncomingMessage): boolean {\n  if (!isLoopbackAddress(request.socket.remoteAddress)) return false\n  const host = request.headers.host\n  if (typeof host !== 'string') return false\n  let hostUrl: URL\n  try {\n    hostUrl = new URL('http://' + host)\n  } catch {\n    return false\n  }\n  if (!isLoopbackHostname(hostUrl.hostname)) return false\n  if (request.headers['sec-fetch-site'] === 'cross-site') return false\n  const origin = request.headers.origin\n  if (origin === undefined) return true\n  try {\n    return new URL(origin).host === hostUrl.host\n  } catch {\n    return false\n  }\n}\n"
    },
    {
      "path": "src/state.ts",
      "content": "/**\n * Host-owned state store for dsh-custom-plugin.\n *\n * One JSON document at `$DSH_HOME/custom-plugin-state.json` holds the\n * appearance configuration, folder tree, prompt library, starred timeline\n * nodes, the balance API key, and the per-day token usage ledger. Writes are\n * atomic (temp file + rename) and serialized (one in-flight write per path),\n * so a crash never truncates the document and concurrent saves never race\n * on the temp file.\n * @module @alexpeng/dsh-custom-plugin/state\n */\n\nimport { mkdir, open, readFile, rename, rm, stat, writeFile } from 'node:fs/promises'\nimport { dirname, join } from 'node:path'\nimport { dshHome } from './dsh-home.ts'\nimport { DEFAULT_CONFIG, type CustomPluginConfig, type CustomPluginState, type FolderNode, type PromptItem, type StarsMap, type UsageMap, type UsageRow } from './protocol.ts'\nimport { createUsageRow, normalizeUsageMap, pruneUsage } from './usage.ts'\n\n/** State file name of this plugin. */\nexport const STATE_FILE = 'custom-plugin-state.json'\n\n/** Default state document. */\nexport function defaultState(): CustomPluginState {\n  return {\n    cfg: { ...DEFAULT_CONFIG },\n    folders: [],\n    prompts: [],\n    stars: {},\n    apiKey: '',\n    usage: {},\n  }\n}\n\n/** Normalize a stored configuration: strip retired keys and fill defaults. */\nexport function normalizeCfg(raw: unknown): CustomPluginConfig {\n  const cfg: CustomPluginConfig = { ...DEFAULT_CONFIG }\n  if (raw === null || typeof raw !== 'object') return cfg\n  const src = raw as Record<string, unknown>\n  for (const key of Object.keys(DEFAULT_CONFIG) as Array<keyof CustomPluginConfig>) {\n    const value = src[key]\n    if (value === undefined) continue\n    const current = cfg[key]\n    if (typeof current === 'boolean') {\n      if (typeof value === 'boolean') (cfg as Record<string, unknown>)[key] = value\n    } else if (typeof current === 'number') {\n      if (typeof value === 'number' && Number.isFinite(value)) (cfg as Record<string, unknown>)[key] = value\n    } else if (typeof current === 'string') {\n      if (typeof value === 'string') (cfg as Record<string, unknown>)[key] = value\n    }\n  }\n  // Budget values are user-facing numeric settings. Keep malformed or stale\n  // values inside the documented range even when they came from an older\n  // state file or an external backup.\n  cfg.monthlyBudgetCny = Math.max(0, cfg.monthlyBudgetCny ?? 0)\n  cfg.budgetWarningPercent = Math.max(1, Math.min(100, cfg.budgetWarningPercent ?? 80))\n  // The aurora preset was removed; migrate a stored value to \"no color\".\n  if (cfg.bg === 'aurora') cfg.bg = 'default'\n  // Retired keys (clouds / wind, and the timeline trio removed with the rail)\n  // are dropped by construction: only the keys listed in DEFAULT_CONFIG are\n  // ever copied.\n  return cfg\n}\n\n/** Normalize one prompt while retaining its stable identity and order. */\nexport function normalizePrompt(raw: unknown): PromptItem | null {\n  if (raw === null || typeof raw !== 'object') return null\n  const src = raw as Record<string, unknown>\n  if (typeof src.id !== 'string' || src.id === '' || typeof src.name !== 'string' || typeof src.text !== 'string') return null\n  return {\n    id: src.id,\n    name: src.name,\n    text: src.text,\n    tags: Array.isArray(src.tags) ? [...new Set(src.tags.filter((tag): tag is string => typeof tag === 'string').map((tag) => tag.trim()).filter(Boolean))] : [],\n    favorite: src.favorite === true,\n    useCount: typeof src.useCount === 'number' && Number.isFinite(src.useCount) && src.useCount >= 0 ? Math.floor(src.useCount) : 0,\n    lastUsedAt: typeof src.lastUsedAt === 'number' && Number.isFinite(src.lastUsedAt) && src.lastUsedAt > 0 ? src.lastUsedAt : undefined,\n  }\n}\n\n/** Merge a persisted document into the default state, ignoring unknown shapes. */\nexport function mergeState(target: CustomPluginState, raw: unknown): void {\n  if (raw === null || typeof raw !== 'object') return\n  const src = raw as Record<string, unknown>\n  if (src.cfg !== undefined) target.cfg = normalizeCfg(src.cfg)\n  if (Array.isArray(src.folders)) {\n    const folders = normalizeFolders(src.folders)\n    if (folders !== null) target.folders = folders\n  }\n  if (Array.isArray(src.prompts)) target.prompts = src.prompts.map(normalizePrompt).filter((item): item is PromptItem => item !== null)\n  if (src.stars !== null && typeof src.stars === 'object' && !Array.isArray(src.stars)) {\n    const stars = normalizeStars(src.stars)\n    if (stars !== null) target.stars = stars\n  }\n  if (typeof src.apiKey === 'string') target.apiKey = src.apiKey\n  if (src.usage !== null && typeof src.usage === 'object' && !Array.isArray(src.usage)) target.usage = normalizeUsageMap(src.usage)\n}\n\n/** Rejection caps for browser-supplied documents. A shape beyond them is\n * rejected outright — never truncated — because the client owns the whole\n * document and a partial accept would silently drop the rest. The depth cap\n * is what keeps a hostile edit from making `JSON.stringify` throw\n * `RangeError` on every later save. */\nconst MAX_FOLDER_DEPTH = 32\nconst MAX_FOLDER_NODES = 2000\nconst MAX_STAR_ENTRIES = 10000\n\nfunction safeKeyPart(value: string): boolean {\n  return value !== '__proto__' && value !== 'constructor' && value !== 'prototype'\n}\n\n/**\n * Validate a folder tree from the browser against the persisted shape:\n * unique non-empty ids, string name, and string-only id lists, bounded in\n * depth and node count. Null on any violation — the caller rejects the edit.\n */\nexport function normalizeFolders(raw: unknown): FolderNode[] | null {\n  if (!Array.isArray(raw)) return null\n  const seen = new Set<string>()\n  let count = 0\n  const walk = (node: unknown, depth: number): FolderNode | null => {\n    if (node === null || typeof node !== 'object') return null\n    const src = node as Record<string, unknown>\n    if (typeof src.id !== 'string' || src.id === '' || seen.has(src.id)) return null\n    if (typeof src.name !== 'string') return null\n    if (!Array.isArray(src.children) || !Array.isArray(src.sessionIds) || !Array.isArray(src.workspaceIds) || !Array.isArray(src.prompts)) return null\n    const strings = (value: unknown[]): string[] | null => value.every((item) => typeof item === 'string') ? [...new Set(value as string[])] : null\n    const sessionIds = strings(src.sessionIds)\n    const workspaceIds = strings(src.workspaceIds)\n    const prompts = strings(src.prompts)\n    if (sessionIds === null || workspaceIds === null || prompts === null) return null\n    if (depth >= MAX_FOLDER_DEPTH) return null\n    if (++count > MAX_FOLDER_NODES) return null\n    seen.add(src.id)\n    const children: FolderNode[] = []\n    for (const child of src.children) {\n      const parsed = walk(child, depth + 1)\n      if (parsed === null) return null\n      children.push(parsed)\n    }\n    return { id: src.id, name: src.name, children, sessionIds, workspaceIds, prompts }\n  }\n  const out: FolderNode[] = []\n  for (const node of raw) {\n    const parsed = walk(node, 0)\n    if (parsed === null) return null\n    out.push(parsed)\n  }\n  return out\n}\n\n/**\n * Validate a star map from the browser: session ids as safe object keys,\n * digit-string sequence keys, `true` values only, bounded total. Null on any\n * violation.\n */\nexport function normalizeStars(raw: unknown): StarsMap | null {\n  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return null\n  const out: StarsMap = {}\n  let total = 0\n  for (const [sessionId, entries] of Object.entries(raw as Record<string, unknown>)) {\n    if (!safeKeyPart(sessionId)) return null\n    if (entries === null || typeof entries !== 'object' || Array.isArray(entries)) return null\n    const clean: Record<string, boolean> = {}\n    for (const [seq, value] of Object.entries(entries as Record<string, unknown>)) {\n      if (value !== true || !/^\\d+$/.test(seq)) return null\n      if (++total > MAX_STAR_ENTRIES) return null\n      clean[seq] = true\n    }\n    out[sessionId] = clean\n  }\n  return out\n}\n\n/** Retry ladder for a transiently unreadable state file (AV scan, sync\n * client, a sharing violation racing the Desktop host's rename). Same\n * cadence as the browser half's load retries, so a slow-locking file heals\n * inside the window the client is still retrying its first read. */\nconst LOAD_RETRY_DELAYS = [1500, 3000, 6000]\n\n/**\n * Reject a syntactically valid document whose collections cannot be persisted\n * safely. Browser edits already pass the same gates; a hand-edited or\n * half-written file must not bypass them, or one malformed tree makes every\n * later `JSON.stringify` throw while the plugin keeps \"loading\" it.\n * @returns a human-readable reason, or null when the shape is safe.\n */\nfunction validateLoadedShape(raw: unknown): string | null {\n  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return 'state document is not a JSON object'\n  const src = raw as Record<string, unknown>\n  if (src.folders !== undefined && normalizeFolders(src.folders) === null) return 'folders tree fails the shape gate'\n  if (src.stars !== undefined && normalizeStars(src.stars) === null) return 'stars map fails the shape gate'\n  return null\n}\n\n/**\n * Load and merge the persisted document into `state`.\n *\n * A missing file (ENOENT) is a fresh install and resolves with defaults. A\n * corrupt or permanently unreadable file is renamed aside before defaults\n * are adopted, so the caller's immediate save cannot destroy the previous\n * bytes. Only when the file is unreadable AND cannot be moved aside does\n * this reject — the caller must then suppress saves, because persisting\n * never-loaded defaults would clobber a document that may be intact.\n */\nexport async function loadStateFile(\n  state: CustomPluginState,\n  home: string = dshHome(),\n  retryDelays: readonly number[] = LOAD_RETRY_DELAYS,\n): Promise<string> {\n  const statePath = join(home, STATE_FILE)\n  let text: string\n  let mtimeMs = 0\n  let size = 0\n  for (let attempt = 0; ; attempt++) {\n    try {\n      // One handle for fstat + read: the baseline identity and the merged\n      // bytes then describe the same document even if another host saves\n      // between the two calls.\n      const handle = await open(statePath, 'r')\n      try {\n        const st = await handle.stat()\n        text = await handle.readFile('utf8')\n        mtimeMs = st.mtimeMs\n        size = st.size\n      } finally {\n        await handle.close()\n      }\n      break\n    } catch (error) {\n      if ((error as NodeJS.ErrnoException)?.code === 'ENOENT') {\n        syncBaselines.set(statePath, null)\n        return statePath\n      }\n      if (attempt < retryDelays.length) {\n        await new Promise((resolve) => { setTimeout(resolve, retryDelays[attempt]) })\n        continue\n      }\n      await quarantineStateFile(statePath, error)\n      syncBaselines.set(statePath, null)\n      return statePath\n    }\n  }\n  let raw: unknown\n  try {\n    raw = JSON.parse(text)\n  } catch (error) {\n    // Unrecoverable in place; keep the bytes aside and start from defaults.\n    await quarantineStateFile(statePath, error)\n    syncBaselines.set(statePath, null)\n    raw = null\n  }\n  if (raw !== null) {\n    const shapeError = validateLoadedShape(raw)\n    if (shapeError !== null) {\n      // Syntactically valid but impossible to persist safely: a tree deeper\n      // than the serializer can handle, or a stars map that would poison\n      // future folds. Preserve the bytes aside exactly like a parse failure\n      // instead of adopting a document whose next save throws forever.\n      await quarantineStateFile(statePath, new Error(shapeError))\n      syncBaselines.set(statePath, null)\n      raw = null\n    }\n  }\n  if (raw !== null) {\n    mergeState(state, raw)\n    syncBaselines.set(statePath, { mtimeMs, size, doc: text })\n  }\n  // Keep the JSON document bounded even when the user has not opened the\n  // usage panel for a long time. The loader saves the normalized state after\n  // this function resolves.\n  pruneUsage(state.usage)\n  return statePath\n}\n\n/**\n * Rename an unusable state document aside, pid-qualified like the atomic\n * save temp: `$DSH_HOME` is shared by every host under it, so two hosts\n * quarantining must not fight over one recovery name. A file that vanished\n * between the failed read and this rename needs no recovery copy; any other\n * rename failure propagates so the caller knows not to save defaults over a\n * document it could neither read nor preserve.\n */\nasync function quarantineStateFile(statePath: string, cause: unknown): Promise<void> {\n  try {\n    await rename(statePath, `${statePath}.corrupt-${process.pid}`)\n  } catch (error) {\n    if ((error as NodeJS.ErrnoException)?.code === 'ENOENT') return\n    throw new Error(`state file unreadable and could not be quarantined (read: ${String((cause as Error)?.message ?? cause)}; rename: ${String((error as Error)?.message ?? error)})`, { cause: error })\n  }\n}\n\n/** In-flight save per state path: concurrent saves queue instead of racing on\n * the rename order. Two writers renaming one temp file is the Windows\n * EPERM/EBUSY source; queuing also coalesces naturally, because each turn\n * serializes the live document when it runs, not when it was requested. */\nconst saveQueues = new Map<string, Promise<void>>()\n\n/**\n * Temp name for an atomic replace, qualified by the writing process.\n *\n * The queue above is per-process, but `$DSH_HOME` is not: dsh Web and dsh\n * Desktop both run hosts against one home (separate profiles, one `$DSH_HOME`),\n * so a fixed temp name would let the two hosts write and rename the same file\n * and hand each other a partially written document.\n */\nexport function tempPathFor(target: string, pid: number = process.pid): string {\n  return `${target}.${pid}.tmp`\n}\n\n/** Atomically persist the state document. Saves to the same path are\n * serialized: a caller awaits its own turn's completion, a failed turn never\n * poisons the queue behind it. Before writing, another host's changes since\n * this process last loaded or saved the file are merged back in (see\n * `mergeExternalChanges`). */\nexport function saveStateFile(state: CustomPluginState, home: string = dshHome()): Promise<void> {\n  const statePath = join(home, STATE_FILE)\n  const turn = (saveQueues.get(statePath) ?? Promise.resolve())\n    .catch(() => {})\n    .then(async () => {\n      await mergeExternalChanges(state, statePath)\n      await mkdir(dirname(statePath), { recursive: true })\n      const doc = JSON.stringify(state)\n      const tmpPath = tempPathFor(statePath)\n      try {\n        await writeFile(tmpPath, doc, 'utf8')\n        await rename(tmpPath, statePath)\n      } catch (error) {\n        // A pid-qualified temp would otherwise survive a failed turn and accumulate.\n        await rm(tmpPath, { force: true }).catch(() => { /* the rename may have landed; nothing left to clean */ })\n        throw error\n      }\n      // Record what this process just made the file look like, so the next\n      // turn can tell its own writes from another host's.\n      const st = await stat(statePath).catch(() => null)\n      syncBaselines.set(statePath, st !== null ? { mtimeMs: st.mtimeMs, size: st.size, doc } : null)\n    })\n  saveQueues.set(statePath, turn)\n  return turn.finally(() => {\n    if (saveQueues.get(statePath) === turn) saveQueues.delete(statePath)\n  })\n}\n\n/** Per-path view of the on-disk document this process last saw: its stat\n * identity and its serialized bytes. `$DSH_HOME` is shared by every dsh host\n * under it (Web + Desktop), so a save must first notice whether another host\n * wrote the file since. `null` marks \"believed absent\"; no entry at all marks\n * \"never loaded through this module\", where a direct save keeps the plain\n * last-writer-wins behavior. */\nconst syncBaselines = new Map<string, { mtimeMs: number; size: number; doc: string } | null>()\n\n/**\n * Fold another host's writes back in before this process saves over them.\n *\n * Each host holds the whole document in memory, so an unchecked save is\n * last-writer-wins and silently discards the other host's usage folds and\n * config edits. When the file's stat identity no longer matches what this\n * process last wrote or loaded, the current bytes are re-read and three-way\n * merged against the last-saved snapshot: sections this process has not\n * touched adopt the external version, the usage ledger unions arithmetically\n * (`theirs + ours − base` per counter — exact for two hosts that both\n * started from `base`), and locally-dirty sections keep the local version.\n *\n * The stat fast path misses only a same-instant, same-length rewrite by\n * another host. An unreadable or undecodable external document falls back to\n * the plain overwrite — the boot-time quarantine remains the backstop for\n * the destructive case.\n */\nasync function mergeExternalChanges(state: CustomPluginState, statePath: string): Promise<void> {\n  const baseline = syncBaselines.get(statePath)\n  if (baseline === undefined) return\n  const st = await stat(statePath).catch(() => null)\n  if (st === null) return // absent (or vanishing mid-check): nothing to merge\n  if (baseline !== null && st.mtimeMs === baseline.mtimeMs && st.size === baseline.size) return\n  const text = await readFile(statePath, 'utf8').catch(() => null)\n  if (text === null) return\n  let theirs: unknown\n  try {\n    theirs = JSON.parse(text)\n  } catch {\n    return // an undecodable external document has nothing mergeable\n  }\n  if (theirs === null || typeof theirs !== 'object') return\n  mergeThreeWay(state, baseline !== null ? safeParse(baseline.doc) : null, theirs as Record<string, unknown>)\n}\n\nfunction safeParse(text: string): CustomPluginState | null {\n  try {\n    return JSON.parse(text) as CustomPluginState\n  } catch {\n    return null\n  }\n}\n\nfunction sameJson(a: unknown, b: unknown): boolean {\n  return JSON.stringify(a) === JSON.stringify(b)\n}\n\nfunction mergeThreeWay(state: CustomPluginState, base: CustomPluginState | null, theirs: Record<string, unknown>): void {\n  const t = theirs as Partial<CustomPluginState>\n  const b = (base ?? {}) as Partial<CustomPluginState>\n  if (sameJson(state.cfg, b.cfg)) state.cfg = normalizeCfg(t.cfg)\n  if (sameJson(state.folders, b.folders) && Array.isArray(t.folders)) state.folders = t.folders as FolderNode[]\n  if (sameJson(state.prompts, b.prompts) && Array.isArray(t.prompts)) state.prompts = t.prompts.map(normalizePrompt).filter((item): item is PromptItem => item !== null)\n  if (sameJson(state.stars, b.stars) && t.stars !== null && typeof t.stars === 'object' && !Array.isArray(t.stars)) state.stars = t.stars as StarsMap\n  if (sameJson(state.apiKey, b.apiKey) && typeof t.apiKey === 'string') state.apiKey = t.apiKey\n  state.usage = mergeUsageThreeWay(state.usage, base?.usage ?? {}, t.usage)\n}\n\nconst USAGE_COUNTER_KEYS = ['in', 'out', 'cacheIn', 'cacheW', 'reason', 'calls', 'peakIn', 'peakCacheIn', 'peakCacheW', 'peakOut'] as const\n\nfunction counterOf(row: UsageRow | undefined, key: (typeof USAGE_COUNTER_KEYS)[number]): number {\n  const value = row?.[key]\n  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : 0\n}\n\n/** Union two hosts' ledgers given the snapshot both last saved. For every\n * counter `theirs + ours − base` is exactly the combined progress when both\n * hosts started from `base` (their session streams are disjoint: separate\n * dsh profiles under one `$DSH_HOME`); clamped at zero so a tampered base\n * cannot drive a row negative. */\nfunction mergeUsageThreeWay(ours: UsageMap, base: UsageMap, theirsRaw: unknown): UsageMap {\n  const theirs = theirsRaw !== null && typeof theirsRaw === 'object' && !Array.isArray(theirsRaw) ? theirsRaw as UsageMap : {}\n  const merged: UsageMap = {}\n  for (const day of new Set([...Object.keys(ours), ...Object.keys(theirs)])) {\n    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(day)) continue\n    const mergedDay: Record<string, UsageRow> = {}\n    for (const model of new Set([...Object.keys(ours[day] ?? {}), ...Object.keys(theirs[day] ?? {})])) {\n      if (model === '__proto__' || model === 'constructor' || model === 'prototype') continue\n      const om = ours[day]?.[model]\n      const tm = theirs[day]?.[model]\n      if (om === undefined && tm === undefined) continue\n      const row = createUsageRow()\n      for (const key of USAGE_COUNTER_KEYS) {\n        ;(row as unknown as Record<string, number>)[key] = Math.max(0, counterOf(tm, key) + counterOf(om, key) - counterOf(base[day]?.[model], key))\n      }\n      row.peakSplitKnown = !(om?.peakSplitKnown === false || tm?.peakSplitKnown === false)\n      mergedDay[model] = row\n    }\n    if (Object.keys(mergedDay).length > 0) merged[day] = mergedDay\n  }\n  pruneUsage(merged)\n  return merged\n}\n"
