      "path": "src/host-service.ts",
      "content": "/**\n * Host service for dsh-custom-plugin: owns the state document and every\n * browser-facing capability (timeline, export, balance, usage scan, Mermaid).\n * The routes in `routes.ts` are a thin HTTP fence over this class.\n * @module @alexpeng/dsh-custom-plugin/host-service\n */\n\nimport type { AttachmentStore } from '@deepseek-ai/dsh-attachment'\nimport type { SessionEventSearchRequest, SessionLogSnapshot, SessionQueryEngine } from '@deepseek-ai/dsh-session-query'\nimport type { SessionEvent, SessionId } from '@deepseek-ai/dsh-session'\nimport { createRequire } from 'node:module'\nimport { readFileSync } from 'node:fs'\nimport { readFile } from 'node:fs/promises'\nimport { createHash } from 'node:crypto'\nimport { buildExportRows, buildMarkdown, buildPdfHtml, eventSearchText, extractTurns, searchKindOf, snippetAround } from './extract.ts'\nimport { readDeepSeekCredential } from './credentials.ts'\nimport { SystemCredentialStore, type CredentialStore } from './system-credentials.ts'\nimport type { BackupImportMode, BalanceInfo, ConversationSearchItem, ConversationSearchKind, ConversationSearchResult, CredentialStorage, CustomPluginBackupV1, CustomPluginPublicState, CustomPluginState, TimelineItem, UsageRow } from './protocol.ts'\nimport { aggregateDayUsage, createUsageRow, dayKey, foldUsageRecord, isPeakHour, mergeUsageRow, pruneUsage, type UsageRecord } from './usage.ts'\nimport { backupPreview, createBackup, importedState, parseBackup, writeRecoveryBackup } from './backup.ts'\nimport { normalizeCfg, normalizeFolders, normalizePrompt, normalizeStars } from './state.ts'\n\nconst USAGE_SCAN_CONCURRENCY = 4\n\n/** CDN fallback version: the exact package this build ships. A hardcoded\n * `mermaid@11.6.0` while the local dependency resolved 11.17.x made the\n * offline and fallback engines diverge in behavior. */\nconst MERMAID_CDN_VERSION = resolveMermaidVersion()\n\nfunction resolveMermaidVersion(): string {\n  try {\n    const require = createRequire(import.meta.url)\n    const pkg = JSON.parse(readFileSync(require.resolve('mermaid/package.json'), 'utf8')) as { version?: unknown }\n    if (typeof pkg.version === 'string' && /^\\d+\\.\\d+\\.\\d+/.test(pkg.version)) return pkg.version\n  } catch {\n    // dependency absent (e.g. an installed package missing the optional tree)\n  }\n  return '11.6.0'\n}\n\ntype UsageScanResult = { ok: true; day: string; usageToday: unknown; scannedSessions: number } | { ok: false; error: string }\ntype MermaidFetchResult = { ok: true; bytes: number } | { ok: false; error: string }\n\ninterface ScanEntry {\n  readable: boolean\n  /** Live usage arrived before this session's read: the whole replay is\n   * already invalidated, later sessions were not even read. */\n  stale?: boolean\n  usage: Record<string, UsageRow>\n}\n\nasync function mapConcurrent<T, R>(items: readonly T[], limit: number, worker: (item: T) => Promise<R>): Promise<R[]> {\n  const results = new Array<R>(items.length)\n  let next = 0\n  const run = async (): Promise<void> => {\n    while (true) {\n      const index = next++\n      if (index >= items.length) return\n      results[index] = await worker(items[index])\n    }\n  }\n  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, () => run()))\n  return results\n}\n\n/** Options the loader entry supplies to the host service. */\nexport interface CustomPluginHostOptions {\n  sessionQuery: SessionQueryEngine\n  /** Persisted state document (mutated in place; the loader owns saving). */\n  state: CustomPluginState\n  /** Resolve the absolute state file path for diagnostics. */\n  statePath: () => string\n  /** Persist the state document now. */\n  saveNow: () => Promise<void>\n  /** Record a bounded client diagnostic line. */\n  reportDiag: (message: string) => void\n  /** Bounded diagnostic ring for the status tool. */\n  diagReports: string[]\n  /** Optional attachment store used to embed images into PDF exports. */\n  attachments?: AttachmentStore | undefined\n  /** Test seam: return the local mermaid engine file path (or null). */\n  localMermaidPath?: () => string | null\n  /** Test seam: read the DeepSeek credential from DSH's credentials file. */\n  readCredential?: () => Promise<string>\n  /** Test seam and optional platform adapter for OS credential storage. */\n  credentialStore?: CredentialStore\n}\n\n/** Host capabilities behind the routes and the agent tool. */\nexport class CustomPluginHost {\n  private readonly sessionQuery: SessionQueryEngine\n  private readonly state: CustomPluginState\n  private readonly statePath: () => string\n  private readonly persistNow: () => Promise<void>\n  private readonly diagReports: string[]\n  private readonly attachments: AttachmentStore | undefined\n  private readonly credentialStore: CredentialStore\n  private readonly sessionModel = new Map<string, string | null>()\n  // Serialize asynchronous state mutations (edits, imports, and scans).\n  // Session events are synchronous, so they are queued while an operation is\n  // waiting on disk or session I/O and folded before the next operation.\n  private stateOperation: Promise<void> = Promise.resolve()\n  private stateOperationActive = false\n  private stateOperationPending = 0\n  private readonly queuedUsage: Array<{ usage: UsageRecord; time?: number; model: string }> = []\n  private usageScanPromise: Promise<UsageScanResult> | null = null\n  private usageRevision = 0\n  private lastUsagePruneDay = ''\n  private mermaidFetchPromise: Promise<MermaidFetchResult> | null = null\n  private mermaidBytesValue = 0\n  private mermaidJs = ''\n  private mermaidSource = ''\n  private mermaidEtagValue = ''\n  private localMermaidPath: () => string | null\n  private readCredential: () => Promise<string>\n  // The credential resolution hits the OS keychain plus a file read; both\n  // /state GET and every save response report it, so the *source* verdict\n  // (never the key) is cached briefly. applyEdit and the legacy migration\n  // invalidate, which keeps a save response truthful about the edit just\n  // applied.\n  private credentialCache: { at: number; status: Pick<CustomPluginPublicState, 'apiKeyConfigured' | 'credentialStorage'> } | null = null\n  private static readonly CREDENTIAL_CACHE_TTL_MS = 5000\n\n  constructor(options: CustomPluginHostOptions) {\n    this.sessionQuery = options.sessionQuery\n    this.state = options.state\n    this.statePath = options.statePath\n    this.persistNow = options.saveNow\n    this.diagReports = options.diagReports\n    this.attachments = options.attachments\n    this.credentialStore = options.credentialStore ?? new SystemCredentialStore()\n    this.localMermaidPath = options.localMermaidPath ?? defaultLocalMermaidPath\n    this.readCredential = options.readCredential ?? readDeepSeekCredential\n  }\n\n  /** Persisted state document (debounced by the loader entry). */\n  async persist(): Promise<void> {\n    await this.persistNow()\n  }\n\n  /** Read one complete session log snapshot. `readSession` replay-validates\n   * through a snapshot-mode constructor that rejects any seeded (forked or\n   * resumed) session whose log outgrew its seed boundary — newer dsh builds\n   * then fail every read with \"seeded session constructor seed must equal its\n   * inherited prefix\". `observeSession` serves the same log through its\n   * live/restore paths without that constructor, so fall back to it before\n   * surfacing the error. */\n  private async readSessionLog(sessionId: string): Promise<SessionLogSnapshot> {\n    const id = sessionId as SessionId\n    try {\n      return await this.sessionQuery.readSession(id)\n    } catch (error) {\n      // The guard stays on purpose: a host without this observation API must\n      // still surface readSession's own error, not a TypeError about a method.\n      const { observeSession } = this.sessionQuery\n      if (typeof observeSession !== 'function') throw error\n      const lease = await observeSession.call(this.sessionQuery, id, { projectionMode: 'none' })\n      const events = [...lease.events]\n      const disposeSymbol = (Symbol as { dispose?: symbol }).dispose\n      if (disposeSymbol !== undefined) {\n        const dispose = (lease as unknown as Record<symbol, unknown>)[disposeSymbol]\n        if (typeof dispose === 'function') (dispose as () => void).call(lease)\n      }\n      return { session: lease.header, events } as unknown as SessionLogSnapshot\n    }\n  }\n\n  /** Persist after all queued state mutations have reached a stable point. */\n  async persistWhenIdle(): Promise<void> {\n    await this.runStateOperation(() => this.persist())\n  }\n\n  private runStateOperation<T>(operation: () => Promise<T>): Promise<T> {\n    this.stateOperationPending++\n    // Mark the gate synchronously, before the promise continuation runs. A\n    // session event delivered in the same turn as an import/edit must not\n    // slip into a stale snapshot between scheduling and execution.\n    this.stateOperationActive = true\n    const run = this.stateOperation.catch(() => {}).then(async () => {\n      try {\n        return await operation()\n      } finally {\n        // Keep the gate closed while persisting the queued events. This\n        // avoids a tiny window in which a new event could bypass the flush.\n        while (this.queuedUsage.length > 0) {\n          const pending = this.queuedUsage.splice(0)\n          for (const item of pending) this.foldUsageNow(item.usage, item.time, item.model)\n          try {\n            await this.persist()\n          } catch (error) {\n            this.pushDiag(`queued usage save failed: ${String((error as Error)?.message ?? error)}`)\n          }\n        }\n        this.stateOperationPending--\n        if (this.stateOperationPending === 0) this.stateOperationActive = false\n      }\n    })\n    this.stateOperation = run.then(() => {}, () => {})\n    return run\n  }\n\n  /** Record a bounded client diagnostic line. */\n  pushDiag(message: string): void {\n    this.diagReports.push(String(message ?? '').slice(0, 400))\n    if (this.diagReports.length > 20) this.diagReports.splice(0, this.diagReports.length - 20)\n  }\n\n  /** Track the model of each session's latest request. */\n  rememberModel(sessionId: string, model: string | null): void {\n    this.sessionModel.set(sessionId, model)\n  }\n\n  forgetSession(sessionId: string): void {\n    this.sessionModel.delete(sessionId)\n  }\n\n  /** Fold one assistant/message usage record into the ledger. The event time\n   * decides both the day bucket and the peak/off-peak portion. */\n  foldUsage(sessionId: string, usage: UsageRecord, time?: number, modelOverride?: string | null): void {\n    const model = modelOverride !== undefined ? (modelOverride ?? 'unknown') : (this.sessionModel.get(sessionId) ?? 'unknown')\n    if (this.stateOperationActive) {\n      this.queuedUsage.push({ usage, time, model })\n      // Count the arrival immediately so an in-flight replay cannot replace\n      // the ledger with a snapshot that predates this event.\n      this.usageRevision++\n      return\n    }\n    this.foldUsageNow(usage, time, model)\n  }\n\n  private foldUsageNow(usage: UsageRecord, time: number | undefined, model: string): void {\n    const at = time ?? Date.now()\n    const dayName = dayKey(at)\n    const day = this.state.usage[dayName] ?? (this.state.usage[dayName] = {})\n    if (this.lastUsagePruneDay !== dayName) {\n      pruneUsage(this.state.usage, at)\n      this.lastUsagePruneDay = dayName\n    }\n    const row = day[model] ?? (day[model] = createUsageRow())\n    foldUsageRecord(row, usage, isPeakHour(at))\n    this.usageRevision++\n  }\n\n  /** Snapshot of browser-safe state; the API key value never crosses this boundary. */\n  async stateView(): Promise<CustomPluginPublicState> {\n    const credential = await this.credentialStatus()\n    return {\n      cfg: this.state.cfg,\n      folders: this.state.folders,\n      prompts: this.state.prompts,\n      stars: this.state.stars,\n      usage: this.state.usage,\n      ...credential,\n    }\n  }\n\n  /** Apply a browser-side state edit (config, folders, prompts, stars, api key). */\n  async applyEdit(edit: { cfg?: Partial<CustomPluginState['cfg']>; folders?: CustomPluginState['folders']; prompts?: CustomPluginState['prompts']; stars?: CustomPluginState['stars']; apiKey?: string }): Promise<void> {\n    this.credentialCache = null\n    await this.runStateOperation(async () => {\n      // Only the edited sections can change, and every setter replaces its\n      // section wholesale. A shallow snapshot is therefore a complete rollback\n      // point; deep-cloning the usage ledger here made every toggle O(ledger)\n      // and grew worse with retention.\n      const previous = {\n        cfg: this.state.cfg,\n        folders: this.state.folders,\n        prompts: this.state.prompts,\n        stars: this.state.stars,\n        apiKey: this.state.apiKey,\n      }\n      try {\n        await this.applyEditNow(edit)\n      } catch (error) {\n        // A credential-store failure must not leave the non-sensitive fields\n        // half-applied in memory while the route reports an error.\n        Object.assign(this.state, previous)\n        throw error\n      }\n    })\n  }\n\n  private async applyEditNow(edit: { cfg?: Partial<CustomPluginState['cfg']>; folders?: CustomPluginState['folders']; prompts?: CustomPluginState['prompts']; stars?: CustomPluginState['stars']; apiKey?: string }): Promise<void> {\n    if (edit.cfg !== undefined && edit.cfg !== null && typeof edit.cfg === 'object') this.state.cfg = normalizeCfg({ ...this.state.cfg, ...edit.cfg })\n    if (Array.isArray(edit.folders)) {\n      const folders = normalizeFolders(edit.folders)\n      // Reject rather than persist: a shape beyond the validators could make\n      // every later save's JSON.stringify throw, and the client owns the full\n      // document, so silent truncation would drop parts of it.\n      if (folders === null) throw new Error('文件夹数据无效')\n      this.state.folders = folders\n    }\n    if (Array.isArray(edit.prompts)) this.state.prompts = edit.prompts.map(normalizePrompt).filter((item): item is NonNullable<ReturnType<typeof normalizePrompt>> => item !== null)\n    if (edit.stars !== undefined && edit.stars !== null && typeof edit.stars === 'object') {\n      const stars = normalizeStars(edit.stars)\n      if (stars === null) throw new Error('星标数据无效')\n      this.state.stars = stars\n    }\n    if (typeof edit.apiKey === 'string') {\n      const key = edit.apiKey.trim()\n      if (key === '') {\n        const cleared = await this.credentialStore.clear()\n        if (this.credentialStore.available && !cleared) throw new Error('系统凭据清除失败，请重试')\n        this.state.apiKey = ''\n      } else {\n        if (!/^sk-/.test(key)) throw new Error('DeepSeek API Key 必须以 sk- 开头')\n        this.state.apiKey = await this.credentialStore.set(key) ? '' : key\n      }\n    }\n  }\n\n  /** Build the portable backup projection; credentials never enter it. */\n  backupExport(): CustomPluginBackupV1 {\n    return createBackup(this.state)\n  }\n\n  /** Validate/preview or atomically apply a portable backup. */\n  async backupImport(raw: unknown, mode: BackupImportMode, dryRun: boolean): Promise<{ ok: true; preview: ReturnType<typeof backupPreview>; recoveryPath?: string } | { ok: false; error: string }> {\n    return await this.runStateOperation(() => this.backupImportNow(raw, mode, dryRun))\n  }\n\n  private async backupImportNow(raw: unknown, mode: BackupImportMode, dryRun: boolean): Promise<{ ok: true; preview: ReturnType<typeof backupPreview>; recoveryPath?: string } | { ok: false; error: string }> {\n    try {\n      if (mode !== 'merge' && mode !== 'replace') return { ok: false, error: '导入模式无效' }\n      const backup = parseBackup(raw)\n      const preview = backupPreview(this.state, backup)\n      if (dryRun) return { ok: true, preview }\n      // Same shallow-rollback reasoning as applyEdit: importedState builds\n      // fresh objects, so section references are enough to undo the commit.\n      const previous = {\n        cfg: this.state.cfg,\n        folders: this.state.folders,\n        prompts: this.state.prompts,\n        stars: this.state.stars,\n        usage: this.state.usage,\n        apiKey: this.state.apiKey,\n      }\n      const recoveryPath = await writeRecoveryBackup(this.statePath(), previous)\n      const next = importedState(previous, backup, mode)\n      Object.assign(this.state, next)\n      try {\n        await this.persist()\n      } catch (error) {\n        Object.assign(this.state, previous)\n        throw error\n      }\n      return { ok: true, preview, recoveryPath }\n    } catch (error) {\n      return { ok: false, error: String((error as Error)?.message ?? error) }\n    }\n  }\n\n  /** Move a legacy plaintext state key into the OS store when available. */\n  async migrateLegacyApiKey(): Promise<boolean> {\n    this.credentialCache = null\n    const key = (this.state.apiKey ?? '').trim()\n    if (!/^sk-/.test(key) || !this.credentialStore.available) return false\n    let existing = ''\n    try {\n      existing = (await this.credentialStore.get()).trim()\n    } catch {\n      // Do not overwrite a credential that could not be read safely.\n      return false\n    }\n    if (existing !== '') {\n      if (/^sk-/.test(existing)) {\n        this.state.apiKey = ''\n        return true\n      }\n      // Keep the legacy value as a compatibility fallback rather than\n      // overwriting an unexpected non-empty OS-store entry.\n      return false\n    }\n    if (!await this.credentialStore.set(key)) return false\n    this.state.apiKey = ''\n    return true\n  }\n\n  /** Timeline nodes for one session, capped to the 400-node tail. The tail cap\n   * bounds the payload (each item carries up to 4k of preview text); 400 keeps\n   * dots available when the GUI deep-loads history. */\n  async timelineGet(sessionId: string): Promise<{ ok: true; sessionId: string; items: TimelineItem[] } | { ok: false; error: string }> {\n    try {\n      const snapshot = await this.readSessionLog(sessionId)\n      return { ok: true, sessionId, items: extractTurns(snapshot.events).slice(-400) }\n    } catch (error) {\n      return { ok: false, error: String((error as Error)?.message ?? error) }\n    }\n  }\n\n  /** Export one session as JSON / Markdown / print-ready HTML. */\n  async exportRun(sessionId: string, format: string): Promise<{ ok: true; content: string; fileName: string; mime: string } | { ok: false; error: string }> {\n    let snapshot\n    try {\n      snapshot = await this.readSessionLog(sessionId)\n    } catch (error) {\n      return { ok: false, error: `读取会话失败: ${String((error as Error)?.message ?? error)}` }\n    }\n    let title = ''\n    try {\n      const titleSnapshot = await this.sessionQuery.readTitle(sessionId as SessionId)\n      if (titleSnapshot !== undefined) title = String((titleSnapshot as { title?: unknown }).title ?? '')\n    } catch {\n      title = ''\n    }\n    const readImage = this.attachments !== undefined\n      ? (ref: Parameters<AttachmentStore['readImage']>[0]) => this.attachments!.readImage(ref)\n      : undefined\n    try {\n      const rows = await buildExportRows(snapshot, format === 'pdf' ? 'pdf' : format === 'json' ? 'json' : 'markdown', readImage)\n      const stamp = `${dayKey()}-${String(Date.now() % 86400000)}`\n      if (format === 'json') {\n        const messages = rows.map((row) => {\n          if (row.kind === 'user') {\n            return { role: 'user', content: row.text, images: (row.images ?? []).map((image) => ({ name: image.name, mediaType: image.mediaType, width: image.width, height: image.height, bytes: image.bytes })) }\n          }\n          if (row.kind === 'assistant') return { role: 'assistant', content: row.text }\n          if (row.kind === 'tool-call') return { role: 'tool', name: row.toolName, arguments: row.toolArgs, content: '' }\n          if (row.kind === 'tool-result') return { role: 'tool', name: row.toolName ?? '', content: row.text }\n          return { role: 'system', content: row.text }\n        })\n        const doc = {\n          meta: {\n            exporter: 'dsh-custom-plugin',\n            version: 1,\n            id: sessionId,\n            title,\n            createdAt: snapshot.session.createdAt ?? null,\n            cwd: snapshot.session.cwd ?? null,\n            exportedAt: new Date().toISOString(),\n            count: messages.length,\n          },\n          messages,\n        }\n        return { ok: true, content: JSON.stringify(doc, null, 2), fileName: `custom-conversation-${stamp}.json`, mime: 'application/json' }\n      }\n      if (format === 'markdown') {\n        return { ok: true, content: buildMarkdown(rows, sessionId), fileName: `custom-conversation-${stamp}.md`, mime: 'text/markdown' }\n      }\n      if (format === 'pdf') {\n        return { ok: true, content: buildPdfHtml(rows, sessionId), fileName: `custom-conversation-${stamp}.html`, mime: 'text/html' }\n      }\n      return { ok: false, error: 'unknown format' }\n    } catch (error) {\n      return { ok: false, error: `构建导出失败: ${String((error as Error)?.message ?? error)}` }\n    }\n  }\n\n  /** Resolve the key and its source without returning either value to the browser. */\n  private async resolveApiKeyWithSource(): Promise<{ key: string; source: CredentialStorage }> {\n    try {\n      const system = (await this.credentialStore.get()).trim()\n      if (/^sk-/.test(system)) return { key: system, source: 'system' }\n    } catch {\n      // OS credential store unavailable — continue through compatibility tiers.\n    }\n    const key = (this.state.apiKey ?? '').trim()\n    if (/^sk-/.test(key)) return { key, source: 'legacy-state' }\n    try {\n      const env = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env\n      // First valid candidate wins: an unset, empty, or non-sk value for one\n      // name must not shadow the next name (mirrors the credential-file tier,\n      // where each ref is checked individually).\n      for (const name of ['DEEPSEEK_API_KEY', 'DEEPSEEK_KEY', 'DEEPSEEK_TOKEN']) {\n        const value = env?.[name]\n        if (typeof value === 'string' && /^sk-/.test(value.trim())) return { key: value.trim(), source: 'environment' }\n      }\n    } catch {\n      // environment unavailable\n    }\n    try {\n      // DSH keeps model keys in $DSH_HOME/.credentials.yaml and never exports\n      // them to the process environment; reuse the same file so a key\n      // configured once in DSH is picked up automatically here.\n      const candidate = await this.readCredential()\n      if (/^sk-/.test(candidate)) return { key: candidate.trim(), source: 'dsh' }\n    } catch {\n      // credential refs unavailable\n    }\n    return { key: '', source: 'none' }\n  }\n\n  /** Search one session and bind hits to a user-turn anchor.\n   *\n   * DSH's indexed event search is the preferred path, but its shipped web\n   * profile composes `session-query-sqlite` with `openAt: never`, so the index\n   * is absent by default and `searchEvents()` rejects. The full log is read for\n   * the anchor map anyway, so a rejected index degrades to a literal scan of\n   * that log instead of failing the whole feature. */\n  async conversationSearch(sessionId: string, query: string, kinds: readonly ConversationSearchKind[]): Promise<{ ok: true; } & ConversationSearchResult | { ok: false; error: string }> {\n    const wanted = new Set(kinds.length > 0 ? kinds : ['user', 'assistant', 'tool'])\n    const eventTypes: Array<SessionEvent['type']> = kinds.length > 0\n      ? kinds.flatMap((kind): Array<SessionEvent['type']> =>\n        kind === 'user' ? ['user/message'] : kind === 'assistant' ? ['assistant/message'] : ['tool/call', 'tool/result'])\n      : []\n    // Typed request, and a synchronous throw must degrade the same way a\n    // rejection does: an engine without the index can fail on the call itself\n    // rather than returning a rejected promise.\n    const request: SessionEventSearchRequest = {\n      sessionId: sessionId as SessionId,\n      query,\n      limit: 100,\n      ...(eventTypes.length > 0 ? { filters: [{ kind: 'type', values: eventTypes }] } : {}),\n    }\n    const indexRead = Promise.resolve()\n      .then(() => this.sessionQuery.searchEvents(request))\n      .then((page) => page, () => null)\n    let snapshot: SessionLogSnapshot\n    let page: Awaited<typeof indexRead>\n    try {\n      const both = await Promise.all([this.readSessionLog(sessionId), indexRead])\n      snapshot = both[0]\n      page = both[1]\n    } catch (error) {\n      return { ok: false, error: String((error as Error)?.message ?? error) }\n    }\n    const anchors = new Map<number, number>()\n    let anchor: number | undefined\n    for (const event of snapshot.events) {\n      if (event.type === 'user/message') anchor = event.seq\n      if (anchor !== undefined) anchors.set(event.seq, anchor)\n    }\n    const items: ConversationSearchItem[] = []\n    if (page !== null) {\n      for (const hit of page.items) {\n        const kind = searchKindOf(hit.type)\n        if (kind === null || !wanted.has(kind)) continue\n        const anchorSeq = anchors.get(hit.seq)\n        if (anchorSeq === undefined) continue\n        items.push({ sessionId, seq: hit.seq, anchorSeq, kind, time: hit.time, snippet: hit.snippet.slice(0, 500) })\n      }\n      return { ok: true, items, hasMore: page.nextCursor !== undefined, source: 'index' }\n    }\n    const needle = query.toLowerCase()\n    let truncated = false\n    for (const event of snapshot.events) {\n      const kind = searchKindOf(event.type)\n      if (kind === null || !wanted.has(kind)) continue\n      const anchorSeq = anchors.get(event.seq)\n      if (anchorSeq === undefined) continue\n      const text = eventSearchText(event)\n      const at = text.toLowerCase().indexOf(needle)\n      if (at < 0) continue\n      // Fill to the cap, and only claim there is more once a match shows up\n      // past it — a log with exactly 100 hits must not report hasMore.\n      if (items.length >= 100) { truncated = true; break }\n      items.push({ sessionId, seq: event.seq, anchorSeq, kind, time: event.time, snippet: snippetAround(text, at, needle.length, 500) })\n    }\n    return { ok: true, items, hasMore: truncated, source: 'scan' }\n  }\n\n  private async resolveApiKey(): Promise<string> {\n    return (await this.resolveApiKeyWithSource()).key\n  }\n\n  /** Browser-safe credential status used by state and save responses. */\n  async credentialStatus(): Promise<Pick<CustomPluginPublicState, 'apiKeyConfigured' | 'credentialStorage'>> {\n    const now = Date.now()\n    if (this.credentialCache !== null && now - this.credentialCache.at < CustomPluginHost.CREDENTIAL_CACHE_TTL_MS) return this.credentialCache.status\n    const resolved = await this.resolveApiKeyWithSource()\n    const status = { apiKeyConfigured: resolved.key !== '', credentialStorage: resolved.source }\n    this.credentialCache = { at: now, status }\n    return status\n  }\n\n  /** Query the DeepSeek balance endpoint (15s timeout). */\n  async balanceGet(): Promise<{ ok: boolean; keyConfigured: boolean; balance?: BalanceInfo | null; error?: string | null; usageToday?: unknown; available?: boolean }> {\n    const usageToday = this.state.usage[dayKey()] ?? {}\n    const key = await this.resolveApiKey()\n    if (key === '') return { ok: false, keyConfigured: false, error: '未配置 DeepSeek API Key（请在额度面板粘贴 sk- 开头的密钥）', usageToday }\n    let response\n    try {\n      response = await this.httpJson('https://api.deepseek.com/user/balance', { Authorization: `Bearer ${key}`, Accept: 'application/json' })\n    } catch (error) {\n      return { ok: false, keyConfigured: true, error: String((error as Error)?.message ?? error), usageToday }\n    }\n    if (!response.ok) return { ok: false, keyConfigured: true, error: response.error ?? '请求失败', usageToday }\n    const json = (response.json ?? {}) as { is_available?: boolean; balance_infos?: Array<{ currency?: string; total_balance?: string; granted_balance?: string; topped_up_balance?: string }> }\n    const infos = json.balance_infos ?? []\n    const info = infos.find((item) => item.currency === 'CNY') ?? infos[0]\n    return {\n      ok: true,\n      keyConfigured: true,\n      available: json.is_available !== false,\n      balance: info !== undefined ? { currency: info.currency ?? '', total: info.total_balance ?? '0', granted: info.granted_balance ?? '0', toppedUp: info.topped_up_balance ?? '0' } : null,\n      error: infos.length > 0 ? null : '响应中无余额信息',\n      usageToday,\n    }\n  }\n\n  /** Re-scan the session logs and rebuild today's usage ledger. Every session\n   * is replayed but only usage events whose own timestamp falls on today are\n   * folded, so sessions created before midnight keep contributing the usage\n   * they produced today. */\n  async usageScan(): Promise<UsageScanResult> {\n    if (this.usageScanPromise !== null) return await this.usageScanPromise\n    const run = this.runStateOperation(() => this.usageScanImpl())\n    this.usageScanPromise = run\n    try {\n      return await run\n    } finally {\n      if (this.usageScanPromise === run) this.usageScanPromise = null\n    }\n  }\n\n  private async usageScanImpl(): Promise<UsageScanResult> {\n    const revisionAtStart = this.usageRevision\n    let records\n    try {\n      records = await this.sessionQuery.listSessions()\n    } catch {\n      return { ok: false, error: '列会话失败' }\n    }\n    const today = dayKey()\n    const agg: Record<string, UsageRow> = {}\n    let scanned = 0\n    const entries = await mapConcurrent(records, USAGE_SCAN_CONCURRENCY, async (record): Promise<ScanEntry> => {\n      // Live usage arriving mid-replay invalidates the whole snapshot anyway;\n      // checking per item (not once at the end) stops paying for session\n      // reads that are already doomed to be discarded — exactly the window\n      // where a streaming conversation invites rescan retries.\n      if (this.usageRevision !== revisionAtStart) return { readable: false, stale: true, usage: {} }\n      try {\n        const snapshot = await this.readSessionLog(record.header.id)\n        const dayUsage = aggregateDayUsage(snapshot.events, today)\n        return { readable: true, usage: dayUsage }\n      } catch {\n        // skip unreadable session\n        return { readable: false, usage: {} }\n      }\n    })\n    let failedSessions = 0\n    for (const entry of entries) {\n      if (entry.stale === true) continue\n      if (!entry.readable) {\n        failedSessions++\n        continue\n      }\n      const models = Object.keys(entry.usage)\n      if (models.length === 0) continue\n      scanned++\n      for (const model of models) {\n        const row = agg[model] ?? (agg[model] = createUsageRow())\n        mergeUsageRow(row, entry.usage[model])\n      }\n    }\n    // Never replace a complete live ledger with a partial replay. The caller\n    // can retry after the unreadable sessions recover.\n    if (failedSessions > 0) return { ok: false, error: '部分会话读取失败，未覆盖现有用量，请稍后重试' }\n    // Live session events may arrive while the asynchronous replay is in\n    // flight. Keep them rather than replacing them with an older snapshot.\n    if (this.usageRevision !== revisionAtStart) return { ok: false, error: '扫描期间产生了新用量，未覆盖现有用量，请稍后重试' }\n    const previousUsage = JSON.parse(JSON.stringify(this.state.usage)) as CustomPluginState['usage']\n    pruneUsage(this.state.usage)\n    this.state.usage[today] = agg\n    try {\n      await this.persist()\n    } catch (error) {\n      this.state.usage = previousUsage\n      return { ok: false, error: `用量保存失败: ${String((error as Error)?.message ?? error)}` }\n    }\n    return { ok: true, day: today, usageToday: this.state.usage[today] ?? {}, scannedSessions: scanned }\n  }\n\n  /** Resolve the Mermaid engine: the bundled `mermaid` dependency on disk\n   * first (no runtime network), CDN mirrors only as a fallback (cached for\n   * the host lifetime). */\n  async mermaidFetch(): Promise<MermaidFetchResult> {\n    if (this.mermaidBytesValue > 0) return { ok: true, bytes: this.mermaidBytesValue }\n    if (this.mermaidFetchPromise !== null) return await this.mermaidFetchPromise\n    const run = this.mermaidFetchImpl()\n    this.mermaidFetchPromise = run\n    try {\n      return await run\n    } finally {\n      if (this.mermaidFetchPromise === run) this.mermaidFetchPromise = null\n    }\n  }\n\n  private async mermaidFetchImpl(): Promise<MermaidFetchResult> {\n    const localPath = this.localMermaidPath()\n    if (localPath !== null && localPath !== '') {\n      try {\n        // Async read: the bundled engine is ~3.5 MB, and a synchronous read\n        // here stalls every Host request behind it during boot.\n        const text = await readFile(localPath, 'utf8')\n        if (text.length > 0) {\n          this.cacheMermaid(text, 'local')\n          return { ok: true, bytes: this.mermaidBytesValue }\n        }\n      } catch {\n        // unreadable local bundle: fall through to the CDN mirrors\n      }\n    }\n    const urls = [\n      `https://cdn.jsdelivr.net/npm/mermaid@${MERMAID_CDN_VERSION}/dist/mermaid.min.js`,\n      `https://fastly.jsdelivr.net/npm/mermaid@${MERMAID_CDN_VERSION}/dist/mermaid.min.js`,\n      `https://unpkg.com/mermaid@${MERMAID_CDN_VERSION}/dist/mermaid.min.js`,\n    ]\n    let text = ''\n    let lastError = ''\n    for (const url of urls) {\n      try {\n        const result = await this.httpText(url)\n        if (result.ok) {\n          if (looksLikeMermaidBundle(result.text)) { text = result.text; break }\n          lastError = `镜像返回了非脚本内容 (${result.text.length} bytes)`\n          continue\n        }\n        lastError = result.error ?? ''\n      } catch (error) {\n        lastError = String((error as Error)?.message ?? error)\n      }\n    }\n    if (text === '') return { ok: false, error: `无法获取 Mermaid 引擎: ${lastError}` }\n    this.cacheMermaid(text, 'cdn')\n    return { ok: true, bytes: this.mermaidBytesValue }\n  }\n\n  /** Cache the engine and its validators. `bytes` is UTF-8 length, not the\n   * JavaScript string length: the status/debug payloads call it bytes, and a\n   * non-ASCII bundle would otherwise under-report the transfer size. */\n  private cacheMermaid(text: string, source: 'local' | 'cdn'): void {\n    this.mermaidJs = text\n    this.mermaidBytesValue = Buffer.byteLength(text, 'utf8')\n    this.mermaidSource = source\n    this.mermaidEtagValue = createHash('sha256').update(text).digest('hex').slice(0, 32)\n  }\n\n  /** The cached Mermaid engine script (served at the script path). */\n  mermaidScript(): string {\n    return this.mermaidJs\n  }\n\n  /** Mermaid engine byte count for diagnostics. */\n  mermaidBytes(): number {\n    return this.mermaidBytesValue\n  }\n\n  /** Cache validator for the engine script ('' while unloaded). */\n  mermaidEtag(): string {\n    return this.mermaidEtagValue\n  }\n\n  /** Where the engine came from: 'local', 'cdn', or '' while unloaded. */\n  mermaidLoadedSource(): string {\n    return this.mermaidSource\n  }\n\n  /** Whether any DeepSeek key source resolves (state, environment, credential\n   * file) — the honest answer behind the panel's \"key configured\" badge.\n   * Goes through the 5s source cache: the status tool and About tab call this\n   * independently of `/state`, and each miss hits the OS keychain plus a file. */\n  async hasApiKey(): Promise<boolean> {\n    return (await this.credentialStatus()).apiKeyConfigured\n  }\n\n  /** Diagnostics snapshot for the status tool and the About tab. */\n  async debugInfo(): Promise<{ statePath: string; today: string; usageToday: unknown; mermaidBytes: number; mermaidSource: string; apiKeySet: boolean; diagReports: string[] }> {\n    return {\n      statePath: this.statePath(),\n      today: dayKey(),\n      usageToday: this.state.usage[dayKey()] ?? {},\n      mermaidBytes: this.mermaidBytesValue,\n      mermaidSource: this.mermaidSource,\n      apiKeySet: await this.hasApiKey(),\n      diagReports: [...this.diagReports],\n    }\n  }\n\n  private async httpText(url: string): Promise<{ ok: true; text: string } | { ok: false; error?: string }> {\n    try {\n      const response = await fetch(url, { method: 'GET', signal: AbortSignal.timeout(15000) })\n      if (!response.ok) {\n        if (response.status === 401 || response.status === 403) return { ok: false, error: `认证失败 (HTTP ${response.status})` }\n        return { ok: false, error: `HTTP ${response.status}` }\n      }\n      return { ok: true, text: await response.text() }\n    } catch (error) {\n      return { ok: false, error: String((error as Error)?.message ?? error) }\n    }\n  }\n\n  private async httpJson(url: string, headers: Record<string, string>): Promise<{ ok: true; json: unknown } | { ok: false; error?: string }> {\n    try {\n      const response = await fetch(url, { method: 'GET', headers, signal: AbortSignal.timeout(15000) })\n      if (!response.ok) {\n        if (response.status === 401 || response.status === 403) return { ok: false, error: '认证失败 (HTTP ' + response.status + ')，请检查 API Key 是否正确' }\n        return { ok: false, error: `HTTP ${response.status}` }\n      }\n      try {\n        return { ok: true, json: await response.json() }\n      } catch {\n        return { ok: false, error: '非 JSON 响应' }\n      }\n    } catch (error) {\n      return { ok: false, error: readableFetchError(error) }\n    }\n  }\n}\n\n/**\n * Translate a Node `fetch` connection-level failure into a message a user can\n * act on. Node reports \"fetch failed\" with the real reason in `error.cause`\n * (e.g. `SELF_SIGNED_CERT_IN_CHAIN` — a local TLS-intercepting proxy or\n * security suite, which makes outbound calls fail *intermittently* whenever\n * the intercept